int read_file_to_buffer(const char* filename, char** output_buffer, size_t* buffer_size) {
    if (filename == NULL || output_buffer == NULL || buffer_size == NULL) {
        return -1; // Invalid input parameters
    }

    // Open the file in binary read mode
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        return -1; // Failed to open file
    }

    // Seek to the end of the file to get its size
    if (fseek(file, 0, SEEK_END) != 0) {
        fclose(file);
        return -1; // Failed to seek to end of file
    }

    // Get the file size
    long file_size = ftell(file);
    if (file_size < 0) {
        fclose(file);
        return -1; // Failed to get file size
    }

    // Reset file pointer to the beginning
    if (fseek(file, 0, SEEK_SET) != 0) {
        fclose(file);
        return -1; // Failed to seek to beginning of file
    }

    // Allocate memory for the file content
    char* buffer = (char*)malloc(file_size + 1); // +1 for null terminator
    if (buffer == NULL) {
        fclose(file);
        return -1; // Failed to allocate memory
    }

    // Read the file content into the buffer
    size_t bytes_read = fread(buffer, 1, file_size, file);
    if (bytes_read != (size_t)file_size) {
        free(buffer);
        fclose(file);
        return -1; // Failed to read complete file content
    }

    // Close the file
    fclose(file);

    // Add null terminator to make it a valid C string
    buffer[file_size] = '\0';

    // Set the output parameters
    *output_buffer = buffer;
    *buffer_size = file_size;

    return 0; // Success
}
